-- Explicações por artigo — Decreto sobre o Uso da Força pelos Profissionais de Segurança Pública. Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Este Decreto disciplina o uso da força e dos instrumentos de menor potencial ofensivo pelos profissionais de segurança pública, com vistas a promover eficiência, transparência, valorização dos profissionais e respeito aos direitos humanos. A classificação dos instrumentos de menor potencial ofensivo obedece ao Estatuto do Desarmamento, à Lei nº 13.060, de 22 de dezembro de 2014, e a decreto específico.', '["Regula o uso da força e dos instrumentos de menor potencial ofensivo.","Objetivos: eficiência, transparência, valorização dos profissionais e direitos humanos.","Classificação dos instrumentos segue o Estatuto do Desarmamento, a Lei nº 13.060 e decreto próprio."]'::jsonb, '["É um DECRETO (ato do Executivo), e não uma lei.","Complementa a Lei nº 13.060, de 22 de dezembro de 2014."]'::jsonb, 'O decreto orienta a polícia a empregar a força de forma proporcional e a respeitar direitos humanos.', '["Assertiva que classifica o ato como lei ordinária erra: é decreto do Executivo."]'::jsonb, '[{"termo":"Instrumento de menor potencial ofensivo","significado":"Equipamento projetado para conter sem causar morte, como o spray de pimenta."}]'::jsonb, '["Lei do Uso Diferenciado da Força"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São princípios gerais do uso da força em segurança pública: legalidade, precaução, necessidade, proporcionalidade, razoabilidade, responsabilização e não discriminação. O uso da força deve observar diretrizes como: ocorrer para um objetivo legal e nos estritos limites da lei; planejar as ações para prevenir ou minimizar o uso da força e mitigar danos; empregar um recurso de força somente quando recursos de menor intensidade não bastarem; compatibilizar o nível da força com a gravidade da ameaça; empregá-la com bom senso, prudência e equilíbrio; responsabilizar órgãos e profissionais pelo uso inadequado, respeitados o devido processo legal, a ampla defesa e o contraditório; e atuar sem discriminação de raça, etnia, cor, gênero, orientação sexual, idioma, religião, nacionalidade, origem social, deficiência, situação econômica ou opinião política.', '["Sete princípios: legalidade, precaução, necessidade, proporcionalidade, razoabilidade, responsabilização e não discriminação.","Força só quando meios menos intensos forem insuficientes.","Nível da força compatível com a gravidade da ameaça.","Responsabilização com devido processo legal.","Atuação sem discriminação."]'::jsonb, '["Mnemônico dos princípios: LPNPRRN (legalidade, precaução, necessidade, proporcionalidade, razoabilidade, responsabilização, não discriminação).","A força é progressiva (do menor ao maior nível)."]'::jsonb, 'O policial usa a verbalização antes de recorrer a instrumentos de menor potencial ofensivo.', '["Assertiva que omite a necessidade e a proporcionalidade do rol de princípios erra."]'::jsonb, '[{"termo":"Proporcionalidade","significado":"Resposta compatível com a gravidade da ameaça."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A força deverá ser utilizada de forma diferenciada, com a seleção apropriada do nível a ser empregado, em resposta a uma ameaça real ou potencial, para minimizar o uso de meios que possam causar ofensas, ferimentos ou mortes. Os profissionais priorizarão a comunicação, a negociação e as técnicas que impeçam uma escalada da violência. O emprego de arma de fogo será medida de último recurso. Não é legítimo o uso de arma de fogo contra pessoa em fuga desarmada ou que não represente risco imediato de morte ou lesão, nem contra veículo que desrespeite bloqueio policial, exceto quando o ato represente risco de morte ou lesão. O emprego de arma de fogo ou de instrumento de menor potencial ofensivo é restrito a profissionais habilitados. Sempre que o uso da força resultar em ferimento ou morte, será elaborado relatório circunstanciado.', '["Uso diferenciado da força.","Prioridade para comunicação e negociação.","Arma de fogo é último recurso.","Vedada contra fugitivo desarmado sem risco imediato e contra veículo que fure bloqueio, salvo risco de morte ou lesão.","Somente profissionais habilitados.","Relatório circunstanciado em caso de ferimento ou morte."]'::jsonb, '["Arma de fogo: ÚLTIMO recurso.","Veículo que fura bloqueio: só há uso legítimo se houver risco de morte ou lesão."]'::jsonb, 'O policial não pode atirar em fugitivo desarmado que não represente risco imediato.', '["Assertiva que autoriza tiro contra qualquer veículo que desrespeite bloqueio erra: exige risco de morte ou lesão."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na capacitação de profissionais de segurança pública sobre o uso da força, os órgãos deverão observar a obrigatoriedade e a periodicidade anual da capacitação; sua realização no horário de serviço; e a adoção de conteúdo sobre o emprego adequado de diferentes tipos de armas de fogo e de instrumentos de menor potencial ofensivo. A matriz curricular nacional deverá ser atualizada para adequação à Lei nº 13.060, de 22 de dezembro de 2014, e a este Decreto.', '["Capacitação obrigatória e anual.","Realizada no horário de serviço.","Conteúdo sobre armas de fogo e instrumentos de menor potencial ofensivo.","Atualização da matriz curricular nacional."]'::jsonb, '["Periodicidade ANUAL."]'::jsonb, 'A corporação realiza o treinamento anual sobre uso da força em horário de serviço.', '["Assertiva que torna facultativa a capacitação anual erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao órgão federal responsável pela segurança pública, para implementar o Decreto, entre outras ações: financiar, conforme a disponibilidade orçamentária, ações de implementação; formular, implementar, monitorar e avaliar ações relacionadas ao uso da força, como diagnósticos, padronização de procedimentos, doutrina, capacitação e aquisições; ofertar consultoria técnica; desenvolver materiais de referência sobre uso de algemas, busca pessoal e domiciliar e atuação em ambientes prisionais; disponibilizar atas de registro de preços para armas e equipamentos; realizar capacitação; incentivar a conscientização e a integração com a sociedade civil; promover boas práticas; fomentar pesquisas; reduzir a vitimização dos profissionais e a letalidade policial; consolidar e publicar dados nacionais; e informar a população sobre as políticas e como reportar condutas inadequadas.', '["Financiamento e consultoria técnica.","Materiais de referência sobre algemas, busca pessoal e domiciliar e ambientes prisionais.","Atas de registro de preços para aquisição de armas e equipamentos.","Redução da vitimização dos profissionais e da letalidade policial.","Consolidação e publicação de dados nacionais."]'::jsonb, '["Rol exemplificativo de ações do órgão federal."]'::jsonb, 'O órgão federal publica dados nacionais sobre o uso da força.', '["Assertiva que restringe as ações do órgão federal ao financiamento erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para implementar o Decreto, os órgãos de segurança pública deverão, entre outras medidas: elaborar e atualizar atos normativos sobre o uso diferenciado da força; registrar e publicar dados; disponibilizar equipamento de proteção individual e, no mínimo, dois instrumentos de menor potencial ofensivo a todo profissional em serviço; instituir programas de atenção à saúde mental de profissionais em ocorrências de alto risco; monitorar e avaliar as ações; reduzir a vitimização e a letalidade policial; capacitar; fomentar pesquisas; normatizar e fiscalizar a identificação dos profissionais, de modo a individualizar suas ações; e normatizar a atuação em gerenciamento de crises, busca pessoal e domiciliar, uso de algemas e providências nos casos de lesão corporal ou morte.', '["Equipamento de proteção e, no mínimo, dois instrumentos de menor potencial ofensivo por profissional.","Programas de saúde mental.","Identificação que permita individualizar as ações.","Normas sobre crises, buscas, algemas e lesão ou morte."]'::jsonb, '["Mínimo de DOIS instrumentos de menor potencial ofensivo por profissional em serviço."]'::jsonb, 'Cada policial em serviço recebe coletes e, no mínimo, dois instrumentos de menor potencial ofensivo.', '["Assertiva que prevê apenas um instrumento de menor potencial ofensivo por profissional erra: são no mínimo dois."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São diretrizes para os mecanismos de fiscalização e controle interno na supervisão do uso da força: garantir a transparência e o acesso público a dados; disponibilizar canais de denúncia e orientações de registro e acompanhamento de reclamações; garantir o processamento eficaz e transparente das reclamações; e fortalecer corregedorias e ouvidorias. As ocorrências relacionadas ao uso da força serão formalmente registradas quando resultarem em lesão corporal ou morte, ou envolverem o emprego de armas de fogo ou de instrumentos de menor potencial ofensivo em ambientes prisionais.', '["Transparência e acesso a dados.","Canais de denúncia e acompanhamento de reclamações.","Fortalecimento de corregedorias e ouvidorias.","Registro formal quando houver lesão ou morte, ou uso de armas em ambiente prisional."]'::jsonb, '["Registro obrigatório nas hipóteses do parágrafo único."]'::jsonb, 'Ocorrência com morte durante ação policial é registrada formalmente.', '["Assertiva que dispensa o registro em caso de lesão corporal erra."]'::jsonb, '[]'::jsonb, '["Art. 3º, §5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ato do Ministro da Justiça e Segurança Pública instituirá o Comitê Nacional de Monitoramento do Uso da Força, com a finalidade de monitorar e avaliar a implementação das políticas de uso da força. O ato disporá sobre a composição, garantida a participação da sociedade civil, as competências e o funcionamento, e preverá, entre as finalidades, relatórios, o acompanhamento do Plano Nacional de Segurança Pública quanto à redução da letalidade policial e da vitimização dos profissionais, indicadores, produção de conhecimento, orientações para programas e articulação com os comitês estaduais e distrital. Estados, Distrito Federal e Municípios, se instituírem comitês, observarão as mesmas finalidades.', '["Comitê Nacional de Monitoramento do Uso da Força.","Participação da sociedade civil.","Relatórios, indicadores e articulação com comitês estaduais.","Entes locais seguem as mesmas finalidades se criarem comitês."]'::jsonb, '["Instituído por ato do Ministro da Justiça e Segurança Pública."]'::jsonb, 'O comitê nacional produz relatórios sobre a letalidade policial.', '["Assertiva que exclui a sociedade civil do comitê erra: sua participação é garantida."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O repasse de recursos do Fundo Nacional de Segurança Pública e do Fundo Penitenciário Nacional para ações que envolvam o uso da força pelos órgãos de segurança pública dos Estados, do Distrito Federal e dos Municípios está condicionado à observância do disposto no Decreto.', '["Repasses do Fundo Nacional de Segurança Pública e do Fundo Penitenciário Nacional.","Condicionados à observância do Decreto."]'::jsonb, '["Mecanismo de indução: sem cumprir o Decreto, não há repasse."]'::jsonb, 'O Estado que ignora as regras do Decreto pode perder repasses federais.', '["Assertiva que dispensa a observância do Decreto para receber repasses erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'uso-forca' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministro de Estado da Justiça e Segurança Pública editará normas complementares necessárias à execução do disposto neste Decreto.', '["Normas complementares pelo Ministro da Justiça e Segurança Pública."]'::jsonb, '["Competência regulamentar do Ministro."]'::jsonb, 'Uma portaria do Ministro detalha o relatório circunstanciado.', '["Assertiva que atribui a edição das normas complementares ao Congresso erra."]'::jsonb, '[]'::jsonb, '["Art. 3º, §5º"]'::jsonb, 'under_review', 'claude'
